-- ── Agent Registry Table ──
-- Each agent is a deployable intelligence unit with specific capabilities,
-- triggers, data sources, and connected workflows.

CREATE TABLE IF NOT EXISTS agent_registry (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  agent_id TEXT UNIQUE NOT NULL,
  name TEXT NOT NULL,
  tagline TEXT,
  description TEXT,
  long_description TEXT,
  icon TEXT DEFAULT '✦',
  color TEXT DEFAULT '#c8ff00',
  capabilities TEXT[] DEFAULT '{}',
  vertical_ids TEXT[] DEFAULT '{}',
  triggers TEXT[] DEFAULT '{}',
  data_sources TEXT[] DEFAULT '{}',
  outputs TEXT[] DEFAULT '{}',
  workflow_ids TEXT[] DEFAULT '{}',
  agent_type TEXT DEFAULT 'specialist',
  category TEXT DEFAULT 'operations',
  is_active BOOLEAN DEFAULT true,
  metadata JSONB DEFAULT '{}',
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Index for vertical lookups
CREATE INDEX IF NOT EXISTS idx_agent_registry_vertical_ids ON agent_registry USING GIN (vertical_ids);

-- Index for agent type
CREATE INDEX IF NOT EXISTS idx_agent_registry_type ON agent_registry (agent_type);

-- ── Seed Data: Med Spa Agents ──
INSERT INTO agent_registry (agent_id, name, tagline, description, long_description, icon, color, capabilities, vertical_ids, triggers, data_sources, outputs, workflow_ids, agent_type, category)
VALUES
  ('client_concierge', 'Client Concierge', 'Your front desk never sleeps', 'Handles bookings, rescheduling, cancellations, and automated follow-ups. Syncs with your calendar and sends smart reminders.', 'The Client Concierge is your 24/7 front desk. It handles every booking, reschedule, and cancellation automatically. It syncs with your calendar, sends smart reminders, optimizes your waitlist, and follows up with clients after every visit. No booking falls through. No client is forgotten.', '✦', '#f472b6', ARRAY['Smart booking management', 'Automated follow-ups', 'Calendar sync', 'Waitlist optimization', 'Post-visit follow-up'], ARRAY['med_spa', 'legal', 'real_estate'], ARRAY['New booking', 'Cancellation', 'No-show', 'Follow-up trigger'], ARRAY['Calendar API', 'CRM', 'Client database'], ARRAY['Booking confirmation', 'Reminder notification', 'Follow-up message', 'Waitlist update'], ARRAY['wf1', 'wf3'], 'frontline', 'operations'),
  ('treatment_intelligence', 'Treatment Intelligence Engine', 'Recommendations that convert', 'Analyzes client history, preferences, and purchase patterns to recommend the right treatments and products.', 'The Treatment Intelligence Engine studies every client''s history, preferences, and purchase patterns to recommend exactly what they need next. It cross-sells intelligently, identifies seasonal trends, and suggests products that complement previous purchases. Every recommendation is personalized and timed for maximum conversion.', '◎', '#f472b6', ARRAY['Personalized treatment matching', 'Cross-sell optimization', 'Seasonal trend analysis', 'Product recommendations', 'Purchase pattern analysis'], ARRAY['med_spa'], ARRAY['Client check-in', 'Purchase event', 'Seasonal change', 'Treatment completion'], ARRAY['Treatment catalog', 'Client history', 'Purchase data', 'Seasonal calendar'], ARRAY['Treatment recommendation', 'Product suggestion', 'Cross-sell alert', 'Trend report'], ARRAY['wf2', 'wf4'], 'analytics', 'intelligence'),
  ('retention_sentinel', 'Retention Sentinel', 'Never lose a client again', 'Monitors engagement patterns, flags at-risk clients before they churn, and triggers re-engagement campaigns automatically.', 'The Retention Sentinel watches every client''s engagement patterns. It identifies disengagement signals early — missed appointments, declining visit frequency, unreviewed offers — and triggers personalized re-engagement campaigns before the client drifts away. It manages loyalty programs and tracks satisfaction scores to ensure every client feels valued.', '◈', '#f472b6', ARRAY['Churn prediction', 'Re-engagement automation', 'Loyalty program management', 'Satisfaction tracking', 'Engagement scoring'], ARRAY['med_spa', 'hotel', 'hr'], ARRAY['Missed appointment', 'Low engagement score', 'Expiring loyalty points', 'Negative feedback'], ARRAY['Engagement metrics', 'Visit history', 'Feedback data', 'Loyalty program'], ARRAY['Churn alert', 'Re-engagement campaign', 'Loyalty reward', 'Satisfaction survey'], ARRAY['wf2', 'wf5'], 'monitor', 'retention'),
  ('marketing_intelligence', 'Marketing Intelligence Agent', 'Campaigns that actually work', 'Optimizes ad spend, tracks ROI, and generates campaign recommendations based on real-time client data.', 'The Marketing Intelligence Agent transforms your ad spend from guesswork to precision. It tracks ROI across every channel, segments your audience for targeted campaigns, generates content that converts, and optimizes budgets in real-time. Every dollar spent is tracked against results.', '▣', '#f472b6', ARRAY['Campaign optimization', 'ROI tracking', 'Audience segmentation', 'Content generation', 'Budget optimization'], ARRAY['med_spa', 'hotel', 'real_estate'], ARRAY['Campaign launch', 'Budget threshold', 'Performance milestone', 'Seasonal event'], ARRAY['Ad platform data', 'Client segments', 'Campaign history', 'ROI data'], ARRAY['Campaign recommendation', 'ROI report', 'Audience segment', 'Content draft'], ARRAY['wf1', 'wf4'], 'analytics', 'marketing'),
  ('operations_orchestrator', 'Operations Orchestrator', 'Everything runs itself', 'Coordinates staff schedules, inventory, supply orders, and daily workflows so you focus on clients, not logistics.', 'The Operations Orchestrator is the backbone of your daily operations. It manages staff schedules, tracks inventory levels, automates supply orders, and coordinates daily workflows. It surfaces conflicts before they happen and ensures every moving part of your business runs smoothly.', '◇', '#f472b6', ARRAY['Staff scheduling', 'Inventory management', 'Supply chain automation', 'Daily ops dashboard', 'Conflict detection'], ARRAY['med_spa', 'hotel'], ARRAY['Shift change', 'Low inventory', 'Schedule conflict', 'Daily opening'], ARRAY['Staff database', 'Inventory system', 'Supplier catalog', 'Calendar'], ARRAY['Staff schedule', 'Re-order alert', 'Daily ops report', 'Conflict alert'], ARRAY['wf1', 'wf3'], 'operations', 'logistics'),

  -- ── Hotel Agents ──
  ('guest_experience_ai', 'Guest Experience AI', 'Every stay is personal', 'Personalizes every guest interaction from pre-arrival preferences to post-stay follow-ups. Learns guest preferences across visits.', 'The Guest Experience AI creates a personalized journey for every guest. It learns preferences across visits, sends pre-arrival communications, customizes in-room settings, and follows up after checkout. Every interaction builds a deeper understanding of each guest.', '◆', '#00d4ff', ARRAY['Preference learning', 'Personalized welcome', 'Stay history tracking', 'Post-stay engagement', 'Pre-arrival communication'], ARRAY['hotel'], ARRAY['New booking', 'Guest arrival', 'Checkout', 'Preference update'], ARRAY['Booking system', 'Guest profiles', 'Preference data', 'Stay history'], ARRAY['Personalized welcome', 'Stay recommendations', 'Post-stay message', 'Preference profile'], ARRAY['wf1', 'wf4'], 'frontline', 'guest'),
  ('concierge_ai', 'Concierge Intelligence', 'Your 24/7 luxury concierge', 'Handles guest requests, restaurant recommendations, spa bookings, room service, and local experiences in natural conversation.', 'The Concierge Intelligence handles every guest request in natural conversation — from dinner reservations to spa bookings, room service orders to local experiences. It learns preferences, makes intelligent recommendations, and coordinates with hotel services seamlessly.', '◎', '#00d4ff', ARRAY['Natural language requests', 'Local recommendations', 'Service booking', 'Multi-language support', 'Preference learning'], ARRAY['hotel'], ARRAY['Guest request', 'Service inquiry', 'Complaint', 'Special request'], ARRAY['Hotel services', 'Local directory', 'Guest preferences', 'Availability'], ARRAY['Request fulfillment', 'Recommendation', 'Service booking', 'Follow-up'], ARRAY['wf1', 'wf3'], 'frontline', 'concierge'),
  ('revenue_optimizer', 'Revenue Optimizer', 'Maximize every room', 'Dynamic pricing engine that adjusts rates based on demand, seasonality, events, and booking patterns in real-time.', 'The Revenue Optimizer dynamically adjusts room rates based on demand, seasonality, local events, and booking patterns. It forecasts occupancy, recommends package deals, and identifies revenue opportunities across your property.', '◈', '#00d4ff', ARRAY['Dynamic pricing', 'Demand forecasting', 'Yield management', 'Package optimization', 'Revenue reporting'], ARRAY['hotel'], ARRAY['Rate change', 'Booking surge', 'Event nearby', 'Low occupancy'], ARRAY['Pricing data', 'Booking system', 'Events calendar', 'Competitor rates'], ARRAY['Rate recommendation', 'Forecast report', 'Package deal', 'Revenue alert'], ARRAY['wf2', 'wf4'], 'analytics', 'revenue'),
  ('operations_sentinel', 'Operations Sentinel', 'Everything behind the scenes', 'Monitors housekeeping, maintenance, F&B, and front desk operations. Flags issues before guests notice them.', 'The Operations Sentinel keeps your entire property running smoothly. It monitors housekeeping schedules, maintenance requests, F&B inventory, and front desk operations. It flags issues before guests notice them and coordinates responses across departments.', '▣', '#00d4ff', ARRAY['Housekeeping coordination', 'Maintenance alerts', 'F&B inventory tracking', 'Front desk oversight', 'Cross-dept coordination'], ARRAY['hotel'], ARRAY['Maintenance request', 'Housekeeping delay', 'Low inventory', 'Guest complaint'], ARRAY['Hotel operations', 'Maintenance system', 'Inventory', 'Staff schedules'], ARRAY['Maintenance alert', 'Ops report', 'Inventory alert', 'Coordination task'], ARRAY['wf1', 'wf3'], 'operations', 'logistics'),
  ('guest_insights_engine', 'Guest Insights Engine', 'Know your guests deeply', 'Aggregates guest feedback, reviews, and behavior data to surface actionable insights for service improvement.', 'The Guest Insights Engine aggregates feedback from every touchpoint — reviews, surveys, direct feedback, and behavioral data. It surfaces actionable insights for service improvement, identifies trends, and helps your team continuously elevate the guest experience.', '◇', '#00d4ff', ARRAY['Sentiment analysis', 'Review aggregation', 'Service improvement suggestions', 'Loyalty optimization', 'Trend identification'], ARRAY['hotel'], ARRAY['New review', 'Feedback submission', 'Survey response', 'Behavioral shift'], ARRAY['Review platforms', 'Feedback system', 'Guest behavior', 'Loyalty data'], ARRAY['Sentiment report', 'Improvement suggestion', 'Trend alert', 'Loyalty recommendation'], ARRAY['wf2', 'wf5'], 'analytics', 'intelligence'),

