  ('property_match', 'Property Match Intelligence', 'The perfect property finds them', 'Pairs buyers with their ideal properties using preference analysis, behavioral data, and market intelligence.', 'The Property Match Intelligence analyzes buyer preferences, viewing behavior, and market data to match them with their ideal property. It learns from every interaction and refines recommendations over time.', '◎', '#a78bfa', ARRAY['Preference matching', 'Behavioral analysis', 'Neighborhood insights', 'Comparative market analysis', 'Recommendation refinement'], ARRAY['real_estate'], ARRAY['New search', 'Property view', 'Preference update', 'Market change'], ARRAY['Property database', 'Buyer preferences', 'Viewing history', 'Market data'], ARRAY['Property match', 'Neighborhood report', 'CMA report', 'Recommendation update'], ARRAY['wf2', 'wf4'], 'analytics', 'intelligence'),
  ('market_intelligence', 'Market Intelligence Engine', 'Know the market before everyone else', 'Tracks neighborhood trends, pricing shifts, days-on-market, and emerging opportunities in real-time.', 'The Market Intelligence Engine tracks every signal in your market — neighborhood trends, pricing shifts, days-on-market, school ratings changes, new developments. It surfaces opportunities before your competition sees them.', '◈', '#a78bfa', ARRAY['Trend tracking', 'Pricing analysis', 'Opportunity detection', 'Competitive intelligence', 'Market reports'], ARRAY['real_estate'], ARRAY['Market shift', 'New listing', 'Price change', 'Development announcement'], ARRAY['MLS data', 'Public records', 'Market feeds', 'Development pipeline'], ARRAY['Market report', 'Opportunity alert', 'Competitive analysis', 'Trend forecast'], ARRAY['wf2', 'wf4'], 'analytics', 'market'),
