  ('client_relations', 'Client Relations Agent', 'Relationships that last beyond closing', 'Manages client communication, referrals, reviews, and long-touch nurture campaigns for repeat and referral business.', 'The Client Relations Agent keeps your relationship with every client strong long after closing. It manages referrals, solicits reviews, sends personalized check-ins, and nurtures past clients for repeat business and referrals.', '✦', '#a78bfa', ARRAY['Communication automation', 'Referral generation', 'Review management', 'Long-touch nurture', 'Milestone reminders'], ARRAY['real_estate', 'legal', 'med_spa'], ARRAY['Closing complete', 'Referral trigger', 'Review request', 'Milestone date'], ARRAY['Client database', 'Referral tracking', 'Review platforms', 'Calendar'], ARRAY['Check-in message', 'Referral request', 'Review prompt', 'Nurture email'], ARRAY['wf3', 'wf5'], 'frontline', 'relations'),

