  ('talent_acquisition', 'Talent Acquisition Agent', 'Hire the best, faster', 'Screens candidates, schedules interviews, ranks applicants, and manages the entire hiring pipeline with intelligent automation.', 'The Talent Acquisition Agent transforms your hiring process. It screens candidates against job requirements, schedules interviews automatically, ranks applicants by fit score, and manages your entire hiring pipeline. Your best candidates never slip through.', '▤', '#fb923c', ARRAY['Candidate screening', 'Interview scheduling', 'Applicant ranking', 'Pipeline management', 'Skill matching'], ARRAY['hr'], ARRAY['New application', 'Interview needed', 'Offer decision', 'Pipeline review'], ARRAY['ATS', 'Job requirements', 'Candidate data', 'Interview availability'], ARRAY['Screening result', 'Interview schedule', 'Ranking score', 'Pipeline report'], ARRAY['wf1', 'wf3'], 'frontline', 'talent'),
  ('onboarding_automator', 'Onboarding Automator', 'Day one starts before day one', 'Handles paperwork, equipment setup, training plans, and compliance docs so every new hire is productive from day one.', 'The Onboarding Automator ensures every new hire hits the ground running. It handles paperwork automatically, coordinates equipment setup, generates personalized training plans, and tracks compliance documents. Day one productivity, zero administrative burden.', '◎', '#fb923c', ARRAY['Paperwork automation', 'Equipment provisioning', 'Training plan generation', 'Compliance tracking', 'Welcome sequence'], ARRAY['hr'], ARRAY['New hire', 'Start date approaching', 'Training milestone', 'Compliance check'], ARRAY['HRIS', 'Equipment inventory', 'Training content', 'Compliance rules'], ARRAY['Completed paperwork', 'Equipment order', 'Training plan', 'Compliance status'], ARRAY['wf1', 'wf3'], 'operations', 'onboarding'),
  ('employee_intelligence', 'Employee Intelligence Engine', 'Know your people deeply', 'Tracks engagement, performance, satisfaction, and growth patterns to surface insights that reduce turnover and boost productivity.', 'The Employee Intelligence Engine gives you deep insight into your workforce. It tracks engagement patterns, performance metrics, satisfaction trends, and growth trajectories. It surfaces insights that reduce turnover, boost productivity, and help every employee reach their potential.', '◈', '#fb923c', ARRAY['Engagement tracking', 'Performance analytics', 'Satisfaction monitoring', 'Growth path mapping', 'Turnover prediction'], ARRAY['hr'], ARRAY['Performance review', 'Engagement dip', 'Promotion eligibility', 'Resignation risk'], ARRAY['HRIS', 'Performance data', 'Engagement surveys', 'Feedback tools'], ARRAY['Engagement report', 'Performance review', 'Growth recommendation', 'Risk alert'], ARRAY['wf2', 'wf5'], 'analytics', 'intelligence'),
