  ('workforce_planner', 'Workforce Planner', 'Right people, right time', 'Analyzes headcount needs, skill gaps, and staffing forecasts to recommend hiring, training, and restructuring decisions.', 'The Workforce Planner gives you strategic workforce intelligence. It analyzes headcount needs, identifies skill gaps, forecasts staffing requirements, and recommends hiring, training, and restructuring decisions aligned with your business goals.', '◇', '#fb923c', ARRAY['Headcount analysis', 'Skill gap mapping', 'Staffing forecasts', 'Organizational planning', 'Budget optimization'], ARRAY['hr'], ARRAY['Quarterly planning', 'Budget cycle', 'Team expansion', 'Skill shortage'], ARRAY['HRIS', 'Financial data', 'Project plans', 'Skills database'], ARRAY['Headcount plan', 'Skill gap report', 'Staffing forecast', 'Org recommendation'], ARRAY['wf4'], 'analytics', 'strategy'),

