  ('document_intelligence', 'Document Intelligence Engine', 'Draft, review, file — automatically', 'Drafts standard documents, reviews contracts for risk, organizes filings, and maintains a searchable knowledge base.', 'The Document Intelligence Engine transforms your document workflow. It drafts standard documents from templates, reviews contracts for risk clauses, organizes filings for easy retrieval, and maintains a searchable knowledge base of your firm''s work product.', '◎', '#34d399', ARRAY['Document drafting', 'Contract review', 'Filing organization', 'Knowledge management', 'Risk identification'], ARRAY['legal'], ARRAY['Document request', 'Contract review needed', 'Filing deadline', 'Knowledge search'], ARRAY['Document templates', 'Contract library', 'Filing system', 'Knowledge base'], ARRAY['Drafted document', 'Contract review', 'Filing package', 'Knowledge match'], ARRAY['wf1', 'wf4'], 'operations', 'document'),
  ('case_coordinator', 'Case Management Coordinator', 'Every deadline met', 'Tracks court dates, filing deadlines, task assignments, and case milestones across every active matter.', 'The Case Management Coordinator ensures nothing falls through the cracks. It tracks every court date, filing deadline, task assignment, and case milestone. It alerts the right person at the right time and provides a complete view of every active matter.', '◈', '#34d399', ARRAY['Deadline tracking', 'Task coordination', 'Milestone monitoring', 'Calendar management', 'Team alerts'], ARRAY['legal'], ARRAY['New case', 'Deadline approaching', 'Task overdue', 'Milestone reached'], ARRAY['Case management system', 'Court calendar', 'Task database', 'Team availability'], ARRAY['Deadline alert', 'Task update', 'Milestone report', 'Calendar sync'], ARRAY['wf1', 'wf3'], 'operations', 'case'),
  ('billing_automation', 'Billing Automation Agent', 'Time tracked, invoices sent', 'Tracks billable hours, generates invoices, manages trust accounts, and follows up on outstanding payments automatically.', 'The Billing Automation Agent captures every billable minute. It tracks time across matters, generates professional invoices, manages trust accounts with precision, and follows up on outstanding payments automatically. Your revenue flows while you focus on clients.', '▣', '#34d399', ARRAY['Time tracking', 'Invoice generation', 'Trust accounting', 'Payment follow-up', 'Revenue reporting'], ARRAY['legal'], ARRAY['Time entry', 'Invoice cycle', 'Payment received', 'Overdue invoice'], ARRAY['Time tracking', 'Matter data', 'Trust accounts', 'Payment processor'], ARRAY['Time report', 'Invoice', 'Trust statement', 'Payment reminder'], ARRAY['wf1', 'wf5'], 'operations', 'billing'),
  ('research_associate', 'Research Associate', 'Find precedent in seconds', 'Searches case law, statutes, and legal databases. Surfaces relevant precedents and summarizes findings for your review.', 'The Research Associate is your always-on legal researcher. It searches case law, statutes, and legal databases in seconds. It surfaces relevant precedents, summarizes findings, and connects research to your active matters. Hours of research compressed into minutes.', '◇', '#34d399', ARRAY['Legal research', 'Precedent analysis', 'Statute lookup', 'Case summarization', 'Matter linking'], ARRAY['legal'], ARRAY['Research request', 'New precedent', 'Statute change', 'Case update'], ARRAY['Legal databases', 'Case law', 'Statutes', 'Active matters'], ARRAY['Research memo', 'Precedent summary', 'Statute update', 'Case alert'], ARRAY['wf2', 'wf4'], 'analytics', 'research')
ON CONFLICT (agent_id) DO UPDATE SET
  name = EXCLUDED.name,
  description = EXCLUDED.description,
  capabilities = EXCLUDED.capabilities,
  vertical_ids = EXCLUDED.vertical_ids,
  updated_at = NOW();

-- ── Agent Vertical Mappings ──
CREATE TABLE IF NOT EXISTS agent_verticals (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  agent_id TEXT NOT NULL REFERENCES agent_registry(agent_id),
  vertical_id TEXT NOT NULL,
  config JSONB DEFAULT '{}',
  is_active BOOLEAN DEFAULT true,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  UNIQUE(agent_id, vertical_id)
);

CREATE INDEX IF NOT EXISTS idx_agent_verticals_vertical ON agent_verticals (vertical_id);

-- ── Agent Workflow Mappings ──
CREATE TABLE IF NOT EXISTS agent_workflows (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  agent_id TEXT NOT NULL REFERENCES agent_registry(agent_id),
  workflow_id TEXT NOT NULL,
  workflow_name TEXT,
  trigger_type TEXT DEFAULT 'event',
  config JSONB DEFAULT '{}',
  is_active BOOLEAN DEFAULT true,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  UNIQUE(agent_id, workflow_id)
);
